SELECT 'REVIEW' AS btype, r.rno AS bno, r.rtitle AS title, r.rdate AS regdate, r.rhit AS hit, CONCAT(CONCAT(b.bname, ' / ★'), r.rrate) AS extraInfo FROM RATING r JOIN BOOK b ON r.bno = b.bno WHERE r.mno = #{mno}
